function e(e,t,n,r=13){let i=Number(e)||0,a=Number(t)||0,o=Math.round(i*a*100)/100,s=Number(r)||0,c=o,l=0;return n===`2`?(l=Math.round(o*s/(100+s)*100)/100,c=Math.round((o-l)*100)/100):n===`3`&&(c=o,l=Math.round(c*s/100*100)/100),{amtn_net:c,tax:l,gross:c+l}}function t(e){let t=0,n=0;for(let r of e)t+=Number(r.amtn_net)||0,n+=Number(r.tax)||0;return{amtn_net:Math.round(t*100)/100,tax:Math.round(n*100)/100,total:Math.round((t+n)*100)/100}}export{t as n,e as t};